WITH customer_summary AS (SELECT customer_id, SUM(CASE WHEN status = 'SHIPPED' THEN amount ELSE 0 END) AS shipped_amount, ROUND((100 * SUM(CASE WHEN channel = 'store' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_store FROM orders WHERE shipping_fee <= 27 GROUP BY customer_id) SELECT c.id, c.signup_date, cs.shipped_amount, cs.pct_store FROM customers c JOIN customer_summary cs ON c.id = cs.customer_id WHERE cs.shipped_amount > 55;
